  { model: 'Gemini 3 Flash', speed: 149, color: '#2dd4bf' },
  { model: 'Gemini 3.1 Pro Preview', speed: 129, color: '#5eead4' },
  { model: 'GPT-5.4 (xhigh)', speed: 72, color: '#5eead4' },
  { model: 'Claude Sonnet 4.6 (max)', speed: 48, color: '#99f6e4' },
  { model: 'GLM-5.1', speed: 40, color: '#99f6e4' },
  { model: 'Claude Opus 4.6 (max)', speed: 40, color: '#ccfbf1' },
  { model: 'DeepSeek V3.2', speed: 31, color: '#ccfbf1' },
];

const pricingData = [
  { model: 'gpt-oss-120B (high)', price: 0.30, color: '#f59e0b' },
  { model: 'DeepSeek V3.2', price: 0.30, color: '#f59e0b' },
