  { model: 'Gemini 3 Flash', price: 1.10, color: '#fbbf24' },
  { model: 'GLM-5.1', price: 2.10, color: '#fbbf24' },
  { model: 'Grok 4.20 0309 v2', price: 3.00, color: '#fcd34d' },
  { model: 'Gemini 3.1 Pro Preview', price: 4.50, color: '#fcd34d' },
