];

// Bubble chart data: x=intelligence, y=speed, size=cost
const bubbleData = [
  { model: 'Gemini 3.1 Pro Preview', intel: 57, speed: 129, cost: 4.50, color: '#3b82f6' },
  { model: 'GPT-5.4', intel: 57, speed: 72, cost: 5.60, color: '#3b82f6' },
