      <div class="bar-track">
        <div class="bar-fill" style="width: ${pct}%; background: ${item.color};">
          <span class="bar-value">${item[valueKey]}${unit ? ' ' + unit : ''}</span>
        </div>
      </div>
    `;
    container.appendChild(row);
  });
}

renderBarChart('intelligence-chart', intelligenceData, 'score', 60, '');
renderBarChart('speed-chart', speedData, 'speed', 220, 'tok/s');
renderBarChart('pricing-chart', pricingData, 'price', 11, '$');

// Bubble chart
function renderBubbleChart() {
  const container = document.getElementById('bubble-chart');
  const w = container.clientWidth;
  const h = container.clientHeight;
  const padding = { top: 40, right: 60, bottom: 80, left: 100 };

  const svgNS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(svgNS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

  const maxIntel = 65;
  const maxSpeed = 230;
  const maxCost = 11;
  const minRadius = 18;
  const maxRadius = 75;

  // Grid lines
  for (let i = 0; i <= 5; i++) {
    const y = padding.top + (h - padding.top - padding.bottom) * (i / 5);
    const line = document.createElementNS(svgNS, 'line');
