    text.setAttribute('x', padding.left - 15);
    text.setAttribute('y', y + 6);
    text.setAttribute('text-anchor', 'end');
    text.setAttribute('fill', '#a0a8b8');
    text.setAttribute('font-size', '20');
    text.textContent = Math.round(maxIntel * (1 - i / 5));
    svg.appendChild(text);
  }

  for (let i = 0; i <= 6; i++) {
    const x = padding.left + (w - padding.left - padding.right) * (i / 6);
    const line = document.createElementNS(svgNS, 'line');
    line.setAttribute('x1', x);
    line.setAttribute('y1', padding.top);
    line.setAttribute('x2', x);
    line.setAttribute('y2', h - padding.bottom);
    line.setAttribute('stroke', 'rgba(255,255,255,0.06)');
    line.setAttribute('stroke-width', '1');
    svg.appendChild(line);

    const text = document.createElementNS(svgNS, 'text');
    text.setAttribute('x', x);
    text.setAttribute('y', h - padding.bottom + 40);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('fill', '#a0a8b8');
    text.setAttribute('font-size', '20');
    text.textContent = Math.round(maxSpeed * (i / 6));
    svg.appendChild(text);
  }

  // Axis labels
  const yLabel = document.createElementNS(svgNS, 'text');
  yLabel.setAttribute('x', 30);
  yLabel.setAttribute('y', h / 2);
  yLabel.setAttribute('text-anchor', 'middle');
  yLabel.setAttribute('fill', '#a0a8b8');
  yLabel.setAttribute('font-size', '24');
  yLabel.setAttribute('font-weight', '600');
  yLabel.setAttribute('transform', `rotate(-90, 30, ${h / 2})`);
  yLabel.textContent = 'Intelligence Score (AA Index)';
  svg.appendChild(yLabel);

  const xLabel = document.createElementNS(svgNS, 'text');
  xLabel.setAttribute('x', w / 2);
  xLabel.setAttribute('y', h - 15);
  xLabel.setAttribute('text-anchor', 'middle');
  xLabel.setAttribute('fill', '#a0a8b8');
  xLabel.setAttribute('font-size', '24');
  xLabel.setAttribute('font-weight', '600');
  xLabel.textContent = 'Output Speed (tokens/sec)';
  svg.appendChild(xLabel);

  // Bubbles
  validBubbleData.forEach(d => {
    const x = padding.left + (d.speed / maxSpeed) * (w - padding.left - padding.right);
    const y = (h - padding.bottom) - (d.intel / maxIntel) * (h - padding.top - padding.bottom);
    const r = minRadius + (d.cost / maxCost) * (maxRadius - minRadius);

    const circle = document.createElementNS(svgNS, 'circle');
    circle.setAttribute('cx', x);
    circle.setAttribute('cy', y);
    circle.setAttribute('r', r);
    circle.setAttribute('fill', d.color);
    circle.setAttribute('opacity', '0.75');
    circle.setAttribute('stroke', 'rgba(255,255,255,0.3)');
    circle.setAttribute('stroke-width', '2');
    svg.appendChild(circle);

    const label = document.createElementNS(svgNS, 'text');
    label.setAttribute('x', x);
    label.setAttribute('y', y + 5);
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#fff');
    label.setAttribute('font-size', '16');
    label.setAttribute('font-weight', '700');
    label.textContent = d.model;
    svg.appendChild(label);

    const sub = document.createElementNS(svgNS, 'text');
    sub.setAttribute('x', x);
    sub.setAttribute('y', y + 24);
    sub.setAttribute('text-anchor', 'middle');
    sub.setAttribute('fill', 'rgba(255,255,255,0.8)');
    sub.setAttribute('font-size', '13');
    sub.textContent = `$${d.cost.toFixed(2)}`;
    svg.appendChild(sub);
  });

  container.appendChild(svg);
}

renderBubbleChart();
</script>

</body>
</html>
