const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const htmlPath = path.resolve('/app/poster.html');
  const outputPath = '/app/output/final_poster.png';

  // Ensure output directory exists
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // A1 portrait at 300 DPI = 3490 x 4943 pixels
  await page.setViewportSize({ width: 3490, height: 4943 });

  const fileUrl = 'file://' + htmlPath;
  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // Wait for fonts to load and bubble chart to render
  await page.waitForTimeout(3000);

